<article><h3>Buttons: sizes and disabled</h3><div class="studio-row"><button v-for="s in ['xs','sm','md','lg']" :key="s" :class="'sk-'+s" @click="toast(s)">{{s}}</button></div><div class="studio-row"><button disabled class="sk-primary">Disabled primary</button><button disabled>Disabled default</button><button disabled class="sk-outline-button">Disabled outline</button></div></article>
