<article><h3>Buttons: active, icons, counters and loading</h3><button :aria-pressed="toggle" :class="{active:toggle}" @click="toggle=!toggle">{{toggle?'Pressed':'Not pressed'}}</button><div class="studio-row"><button @click="count++">+ Add <span class="sk-badge">{{count}}</span></button><button @click="toast('Export sample')">Export ↗</button><button class="sk-primary" :disabled="busy" @click="run">{{busy?'Working…':'Run loading demo'}}</button></div></article>
<article><h3>Button groups: sizes, toolbar and vertical</h3><div class="studio-row" v-for="size in ['sm','md','lg']" :key="size"><div class="sk-group"><button v-for="v in ['Left','Middle','Right']" :key="v" :class="'sk-'+size" @click="toast(v)">{{v}}</button></div></div><div class="studio-row" role="toolbar" aria-label="Sample edit toolbar"><button @click="toast('Bold sample')">B</button><button @click="toast('Italic sample')">I</button><button @click="toast('Link sample')">↗</button></div><div class="sk-vertical"><button v-for="v in ['Overview','Activity','Settings']" :key="v" @click="toast(v)">{{v}}</button></div></article>
